/**
 * ERP numbering utilities — serial/row numbers and document/transaction numbers.
 *
 * <p><b>Authority rule:</b> a persisted document number (PO number, voucher number,
 * invoice number) is ALWAYS generated by the backend inside the saving transaction —
 * that is the only way to keep a gapless, race-free sequence. Nothing here invents a
 * number that gets saved. These helpers exist to <i>format</i>, <i>pad</i>, <i>parse</i>
 * and <i>display</i> numbers consistently, and to compute the purely presentational
 * serial (`#`) column in grids.</p>
 */

// ─── Serial / row numbers ─────────────────────────────────────────────────────

/**
 * Serial number for a grid row.
 *
 * @param rowIndex   zero-based index within the CURRENT sort/filter order
 * @param pageIndex  zero-based page index (ignored when `mode` is `'per-page'`)
 * @param pageSize   rows per page
 * @param mode       `'continuous'` numbers across pages (page 2 starts at 11);
 *                   `'per-page'` restarts at 1 on every page
 */
export function serialNumber(
  rowIndex: number,
  pageIndex = 0,
  pageSize = 0,
  mode: 'continuous' | 'per-page' = 'continuous',
): number {
  if (mode === 'per-page' || !pageSize) return rowIndex + 1;
  return pageIndex * pageSize + rowIndex + 1;
}

// ─── Document / transaction numbers ───────────────────────────────────────────

export interface DocumentNumberFormat {
  /** Module/document prefix, e.g. `'PO'`, `'INV'`, `'JV'`. */
  prefix: string;
  /** Zero-padding width for the sequence. Defaults to 6 → `000123`. */
  width?: number;
  /** Segment separator. Defaults to `'-'`. */
  separator?: string;
  /** Include a year segment between prefix and sequence. */
  year?: number | string;
  /** Optional branch/company code segment, placed after the prefix. */
  scope?: string;
  /** Optional trailing suffix (revision, amendment…). */
  suffix?: string;
}

/**
 * Build a display document number.
 *
 * ```ts
 * formatDocumentNumber(123, { prefix: 'PO', year: 2026 })            // PO-2026-000123
 * formatDocumentNumber(7, { prefix: 'JV', width: 4, scope: 'DHK' })  // JV-DHK-0007
 * ```
 */
export function formatDocumentNumber(
  sequence: number | string | null | undefined,
  format: DocumentNumberFormat,
): string {
  if (sequence == null || sequence === '') return '';

  const { prefix, width = 6, separator = '-', year, scope, suffix } = format;
  const digits = String(sequence).replace(/\D/g, '');
  const padded = digits.padStart(width, '0');

  return [prefix, scope, year, padded, suffix]
    .filter((part) => part !== undefined && part !== null && String(part) !== '')
    .join(separator);
}

/**
 * Split a formatted document number back into its parts. Returns `null` when the
 * value carries no numeric sequence.
 *
 * <p>The sequence is taken from the LAST all-digit segment, so a numeric scope or
 * year segment is not mistaken for the sequence.</p>
 */
export function parseDocumentNumber(
  value: string | null | undefined,
  separator = '-',
): { segments: string[]; sequence: number } | null {
  if (!value) return null;

  const segments = String(value).split(separator);
  for (let i = segments.length - 1; i >= 0; i--) {
    if (/^\d+$/.test(segments[i])) {
      return { segments, sequence: Number(segments[i]) };
    }
  }
  return null;
}

/** Zero-pad a number for display (`padNumber(7, 4)` → `'0007'`). */
export function padNumber(value: number | string | null | undefined, width = 6): string {
  if (value == null || value === '') return '';
  return String(value).padStart(width, '0');
}

/**
 * Next sequence from a list of existing document numbers — for CLIENT-SIDE
 * previews only (a "next number will look like…" hint). Never save this; the
 * backend owns the real sequence.
 */
export function previewNextSequence(
  existing: Array<string | null | undefined>,
  separator = '-',
): number {
  const highest = existing.reduce<number>((max, doc) => {
    const parsed = parseDocumentNumber(doc, separator);
    return parsed && parsed.sequence > max ? parsed.sequence : max;
  }, 0);
  return highest + 1;
}
